  FROM price_ticks
  WHERE symbol = v_pos.market
  ORDER BY created_at DESC, id DESC
  LIMIT 1;

  IF v_pos.first_breach_at IS NULL THEN
    UPDATE futures_positions
       SET first_breach_tick_id = v_tick_id,
